// Generates supabase/seed.sql from lib/catalog.ts.  Run: node scripts/gen-seed.ts
import { writeFileSync } from "node:fs";
import { SEED_COMBOS, SEED_PRODUCTS, SEED_SETTINGS } from "../lib/catalog.ts";

const q = (s: string | null) => (s === null ? "null" : `'${s.replace(/'/g, "''")}'`);

const lines: string[] = [
  "-- Generated by scripts/gen-seed.ts. Edit lib/catalog.ts, then regenerate.",
  "",
  "insert into public.products (id, slug, name_en, name_ta, category, price_per_kg, sell_sizes, low_stock_g, sort) values",
  SEED_PRODUCTS.map(
    (p) =>
      `  (${q(p.id)}, ${q(p.slug)}, ${q(p.name_en)}, ${q(p.name_ta)}, ${q(p.category)}, ${p.price_per_kg}, '{${p.sell_sizes.join(",")}}', ${p.low_stock_g}, ${p.sort})`,
  ).join(",\n") + "\non conflict (id) do nothing;",
  "",
  "insert into public.combos (id, slug, name_en, name_ta, price, packing_charge, low_stock_boxes, sort) values",
  SEED_COMBOS.map(
    (c) => `  (${q(c.id)}, ${q(c.slug)}, ${q(c.name_en)}, ${q(c.name_ta)}, ${c.price}, ${c.packing_charge}, ${c.low_stock_boxes}, ${c.sort})`,
  ).join(",\n") + "\non conflict (id) do nothing;",
  "",
  "insert into public.combo_items (combo_id, product_id, grams) values",
  SEED_COMBOS.flatMap((c) => c.items.map((it) => `  (${q(c.id)}, ${q(it.product_id)}, ${it.grams})`)).join(",\n") +
    "\non conflict do nothing;",
  "",
  "update public.settings set",
  `  closed_message_en = ${q(SEED_SETTINGS.closed_message_en)},`,
  `  closed_message_ta = ${q(SEED_SETTINGS.closed_message_ta)},`,
  `  local_radius_km = ${SEED_SETTINGS.local_radius_km},`,
  `  allowed_state = ${q(SEED_SETTINGS.allowed_state)}`,
  "where id = 1;",
  "",
  "-- Only the slab you gave (within 5 km: ₹100). Add the rest in Admin → Settings → Delivery.",
  "insert into public.delivery_slabs (from_km, to_km, fee, eta_label_en, eta_label_ta)",
  "select 0, 5, 100, 'Delivered within a day', 'ஒரு நாளுக்குள் டெலிவரி'",
  "where not exists (select 1 from public.delivery_slabs);",
  "",
];

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log(`seed.sql: ${SEED_PRODUCTS.length} products, ${SEED_COMBOS.length} combos`);
